"""
Day 10: Lord Shri Ram Sketch & Happy Diwali Devotional Art
30 Days Python Challenge by Tejas (@Tejas0113)

Description:
An authentic saffron-gold line sketch of Lord Shri Ram with Kodanda Bow, Tarkash Quiver,
and sacred tilak, rendered stroke-by-stroke using Python Turtle graphics, accompanied by
a festive Happy Diwali blessing and traditional glowing diyas.
"""

import base64
import json
import turtle as t
import zlib

# Compressed vector stroke paths extracted from the sacred sketch
_RAM_SKETCH_DATA = ""


def get_sketch_paths():
    """Decompresses and returns the vector stroke polylines."""
    raw = zlib.decompress(base64.b64decode(_RAM_SKETCH_DATA))
    return json.loads(raw.decode("utf-8"))


def draw_diya(t_pen, x, y, scale=1.0):
    """Draws a small ornamental glowing terracotta diya at (x, y)."""
    t_pen.penup()
    t_pen.goto(x - 22 * scale, y)
    t_pen.pendown()

    # Clay bowl
    t_pen.pencolor("#B85D19")
    t_pen.fillcolor("#A04812")
    t_pen.begin_fill()
    t_pen.goto(x - 14 * scale, y - 10 * scale)
    t_pen.goto(x + 14 * scale, y - 10 * scale)
    t_pen.goto(x + 22 * scale, y)
    t_pen.goto(x, y - 2 * scale)
    t_pen.goto(x - 22 * scale, y)
    t_pen.end_fill()

    # Golden rim
    t_pen.pencolor("#FFD700")
    t_pen.pensize(2)
    t_pen.penup()
    t_pen.goto(x - 22 * scale, y)
    t_pen.pendown()
    t_pen.goto(x + 22 * scale, y)
    t_pen.penup()

    # Outer flame
    t_pen.goto(x, y + 2 * scale)
    t_pen.pencolor("#FF7A00")
    t_pen.fillcolor("#FFA500")
    t_pen.begin_fill()
    t_pen.goto(x - 7 * scale, y + 9 * scale)
    t_pen.goto(x, y + 24 * scale)
    t_pen.goto(x + 7 * scale, y + 9 * scale)
    t_pen.goto(x, y + 2 * scale)
    t_pen.end_fill()

    # Inner bright flame core
    t_pen.goto(x, y + 4 * scale)
    t_pen.pencolor("#FFF0A0")
    t_pen.fillcolor("#FFFCE0")
    t_pen.begin_fill()
    t_pen.goto(x - 3 * scale, y + 9 * scale)
    t_pen.goto(x, y + 17 * scale)
    t_pen.goto(x + 3 * scale, y + 9 * scale)
    t_pen.goto(x, y + 4 * scale)
    t_pen.end_fill()
    t_pen.penup()


def draw_ram_diwali():
    """Draws Lord Shri Ram and writes the Happy Diwali blessing."""
    # Setup Window & Coordinates
    screen = t.Screen()
    screen.setup(width=880, height=940)
    screen.title("Day 10: Lord Shri Ram Drawing - Happy Diwali")
    screen.bgcolor("#05070E")
    t.setworldcoordinates(-440, -490, 440, 450)

    # Fast and smooth animated stroke rendering
    t.tracer(4, 6)
    t.hideturtle()
    t.speed(0)

    paths = get_sketch_paths()

    # 1. Draw glowing saffron/amber sketch of Lord Shri Ram
    t.pensize(2)
    t.pencolor("#FF9933")

    scale = 1.45
    y_offset = 80
    x_center = 250
    y_center = 240

    for path in paths:
        t.penup()
        p0 = path[0]
        t.goto((p0[0] - x_center) * scale, (y_center - p0[1]) * scale + y_offset)
        t.pendown()
        for pt in path[1:]:
            t.goto((pt[0] - x_center) * scale, (y_center - pt[1]) * scale + y_offset)

    t.penup()

    # 2. Draw traditional glowing Diyas flanking the greeting
    draw_diya(t, -220, -325, scale=1.1)
    draw_diya(t, 220, -325, scale=1.1)

    # 3. Festive & Sacred Typography
    t.penup()

    # Jay Shree Ram Devanagari Title
    t.goto(0, -275)
    t.pencolor("#FFD700")
    t.write("|| जय श्री राम ||", align="center", font=("Devanagari MT", 26, "bold"))

    # Golden Divider Line
    t.pensize(2)
    t.goto(-160, -295)
    t.pendown()
    t.goto(160, -295)
    t.penup()

    # Happy Diwali Greeting
    t.goto(0, -345)
    t.pencolor("#FFA028")
    t.write("HAPPY DIWALI", align="center", font=("Arial", 34, "bold"))

    # Festive Blessings
    t.goto(0, -395)
    t.pencolor("#FFF2D1")
    t.write(
        "May the Divine Grace of Lord Shri Ram Illuminate Your Life",
        align="center",
        font=("Georgia", 14, "normal")
    )

    t.goto(0, -425)
    t.pencolor("#E0BE82")
    t.write(
        "With Peace, Health, Happiness & Infinite Prosperity",
        align="center",
        font=("Georgia", 14, "normal")
    )

    t.update()


def main():
    try:
        draw_ram_diwali()
        t.done()
    except (t.Terminator, KeyboardInterrupt, Exception):
        pass


if __name__ == "__main__":
    main()
